<template>
  <q-page class="q-pa-lg">
    <!-- Header -->
    <div class="row items-center justify-between q-mb-md">
      <div>
        <div class="text-h5 text-weight-bold">
          <q-icon name="psychology" color="primary" class="q-mr-sm" />
          Cấu hình Hệ thống AI & Hồ sơ Prompt
        </div>
        <div class="text-caption text-grey-6">
          Quản lý Server VLM Thị giác (GLM / Qwen), Audio AI (STT & Bất thường âm thanh) và các bộ Prompt phân tích học đường
        </div>
      </div>
      <q-btn outline color="primary" icon="refresh" label="Tải lại" @click="loadAll" />
    </div>

    <div class="row q-col-gutter-lg">
      <!-- 1. Server AI VLM (Thị giác & Suy luận đa phương thức) -->
      <div class="col-12 col-lg-6">
        <q-card class="q-mb-md">
          <q-card-section class="row items-center justify-between">
            <div>
              <div class="text-subtitle1 text-weight-bold text-primary">
                <q-icon name="visibility" class="q-mr-sm" />
                Mô hình Thị giác VLM (Visual Language Model)
              </div>
              <div class="text-caption text-grey-6">
                Cụm GPU NVIDIA H200 suy luận đa khung hình video và đánh giá rủi ro an ninh
              </div>
            </div>
            <q-badge color="purple-9" text-color="white" label="VLM ENGINE" />
          </q-card-section>
          <q-separator />

          <q-card-section>
            <q-form @submit.prevent="saveVlmConfig" class="q-gutter-md">
              <q-input
                v-model="vlm.server_url"
                label="URL Máy chủ VLM (OpenAI-compatible) *"
                placeholder="https://llm.ttpmsandbox.us.kg/v1"
                outlined
                dense
                :rules="[v => !!v || 'Bắt buộc nhập Server URL']"
              >
                <template #prepend><q-icon name="dns" color="primary" /></template>
              </q-input>

              <div class="row q-col-gutter-md">
                <div class="col-12 col-sm-7">
                  <q-select
                    v-model="vlm.model_name"
                    :options="vlmModelOptions"
                    label="Tên Mô hình VLM *"
                    outlined
                    dense
                  >
                    <template #prepend><q-icon name="memory" color="primary" /></template>
                  </q-select>
                </div>
                <div class="col-12 col-sm-5">
                  <q-input
                    v-model.number="vlm.dense_frames_count"
                    type="number"
                    label="Số frame trích xuất"
                    hint="Mặc định: 8 khung hình/clip"
                    outlined
                    dense
                    min="2"
                    max="16"
                  >
                    <template #prepend><q-icon name="movie" color="primary" /></template>
                  </q-input>
                </div>
              </div>

              <q-input
                v-model="vlm.api_key"
                :type="showVlmKey ? 'text' : 'password'"
                label="Khóa API VLM (Bỏ trống nếu giữ nguyên)"
                placeholder="Nhập khóa API mới nếu thay đổi"
                outlined
                dense
              >
                <template #prepend><q-icon name="vpn_key" color="primary" /></template>
                <template #append>
                  <q-icon
                    :name="showVlmKey ? 'visibility_off' : 'visibility'"
                    class="cursor-pointer"
                    @click="showVlmKey = !showVlmKey"
                  />
                </template>
              </q-input>

              <div class="row items-center justify-between text-caption text-grey-7 bg-grey-1 q-pa-sm rounded-borders">
                <span>Khóa API: <b>{{ vlm.has_api_key ? '✅ Đã cấu hình' : '⚠️ Chưa có khóa' }}</b></span>
                <span>Mô hình đang chạy: <b class="text-primary">{{ vlm.model_name }}</b></span>
              </div>

              <!-- Test VLM Connection Result Box -->
              <div v-if="vlmTestResult" class="q-pa-sm rounded-borders" :class="vlmTestResult.connected ? 'bg-green-1 text-positive' : 'bg-red-1 text-negative'">
                <div class="row items-center">
                  <q-icon :name="vlmTestResult.connected ? 'check_circle' : 'error'" size="20px" class="q-mr-xs" />
                  <span class="text-weight-bold">{{ vlmTestResult.connected ? 'Kết nối VLM Server thành công!' : 'Kết nối VLM Server thất bại' }}</span>
                  <q-space />
                  <span v-if="vlmTestResult.latency_ms" class="text-caption">Độ trễ: {{ vlmTestResult.latency_ms }} ms</span>
                </div>
                <div v-if="vlmTestResult.reply" class="text-caption text-grey-8 q-mt-xs">
                  Phản hồi: <i>"{{ vlmTestResult.reply }}"</i>
                </div>
                <div v-if="vlmTestResult.error" class="text-caption text-negative q-mt-xs">
                  Chi tiết: {{ vlmTestResult.error }}
                </div>
              </div>

              <div class="row justify-between items-center q-pt-sm">
                <q-btn
                  outline
                  color="purple"
                  icon="network_check"
                  label="Kiểm tra kết nối VLM"
                  @click="testVlmConnection"
                  :loading="testingVlm"
                />
                <q-btn
                  unelevated
                  color="primary"
                  icon="save"
                  label="Lưu Cấu Hình VLM"
                  type="submit"
                  :loading="savingVlm"
                />
              </div>
            </q-form>
          </q-card-section>
        </q-card>

        <!-- 2. Server Audio AI & Lọc nhiễu DeepFilter -->
        <q-card>
          <q-card-section class="row items-center justify-between">
            <div>
              <div class="text-subtitle1 text-weight-bold text-primary">
                <q-icon name="graphic_eq" class="q-mr-sm" />
                Mô hình Âm thanh & Lọc Nhiễu DeepFilter
              </div>
              <div class="text-caption text-grey-6">
                Bóc tách giọng nói tiếng Việt (STT) và phát hiện âm học bất thường (la hét, va chạm)
              </div>
            </div>
            <q-badge color="teal-9" text-color="white" label="AUDIO AI" />
          </q-card-section>
          <q-separator />

          <q-card-section>
            <q-form @submit.prevent="saveAudioConfig" class="q-gutter-md">
              <q-input
                v-model="audio.server_url"
                label="URL Máy chủ Audio AI *"
                placeholder="https://llm.ttpmsandbox.us.kg/v1/audio"
                outlined
                dense
                :rules="[v => !!v || 'Bắt buộc nhập Server URL']"
              >
                <template #prepend><q-icon name="volume_up" color="primary" /></template>
              </q-input>

              <q-input
                v-model="audio.model_name"
                label="Tên Mô hình Audio AI"
                outlined
                dense
              >
                <template #prepend><q-icon name="hearing" color="primary" /></template>
              </q-input>

              <q-input
                v-model="audio.api_key"
                :type="showAudioKey ? 'text' : 'password'"
                label="Khóa API Audio (Bỏ trống nếu giữ nguyên)"
                placeholder="Nhập khóa API mới nếu thay đổi"
                outlined
                dense
              >
                <template #prepend><q-icon name="key" color="primary" /></template>
                <template #append>
                  <q-icon
                    :name="showAudioKey ? 'visibility_off' : 'visibility'"
                    class="cursor-pointer"
                    @click="showAudioKey = !showAudioKey"
                  />
                </template>
              </q-input>

              <div class="row items-center justify-between bg-grey-1 q-pa-sm rounded-borders">
                <div>
                  <div class="text-weight-bold text-body2">Lọc khử nhiễu DeepFilterNet 3</div>
                  <div class="text-caption text-grey-6">Tiền xử lý âm thanh 16 kHz Mono tại biên trước khi gửi server</div>
                </div>
                <q-toggle v-model="audio.use_deepfilter" color="positive" />
              </div>

              <div class="row justify-end q-pt-sm">
                <q-btn
                  unelevated
                  color="primary"
                  icon="save"
                  label="Lưu Cấu Hình Audio"
                  type="submit"
                  :loading="savingAudio"
                />
              </div>
            </q-form>
          </q-card-section>
        </q-card>
      </div>

      <!-- 3. Hồ sơ Chỉ thị Prompt VLM (Cosmos Prompt Profiles) -->
      <div class="col-12 col-lg-6">
        <q-card class="full-height">
          <q-card-section class="row items-center justify-between">
            <div>
              <div class="text-subtitle1 text-weight-bold text-primary">
                <q-icon name="description" class="q-mr-sm" />
                Hồ sơ Chỉ thị Prompt VLM (Cosmos Profiles)
              </div>
              <div class="text-caption text-grey-6">
                Chỉ định kịch bản phân tích hành vi đặc thù học đường cho mô hình VLM
              </div>
            </div>
            <q-badge color="amber-9" text-color="white" label="SYSTEM PROMPT" />
          </q-card-section>
          <q-separator />

          <q-card-section class="q-gutter-md">
            <div class="row q-col-gutter-sm items-center">
              <div class="col-8">
                <q-select
                  v-model="cosmos.selected"
                  :options="cosmos.profiles"
                  label="Chọn Hồ sơ Prompt đang kích hoạt *"
                  outlined
                  dense
                  @update:model-value="onProfileChange"
                >
                  <template #prepend><q-icon name="tune" color="primary" /></template>
                </q-select>
              </div>
              <div class="col-4">
                <q-btn
                  unelevated
                  color="primary"
                  icon="save"
                  label="Áp dụng"
                  class="full-width"
                  @click="saveCosmos"
                  :loading="savingCosmos"
                />
              </div>
            </div>

            <!-- Upload Custom Prompt -->
            <div class="row q-col-gutter-sm items-center">
              <div class="col-8">
                <q-file
                  v-model="uploadFile"
                  label="Tải lên profile prompt mới (.txt)"
                  outlined
                  dense
                  accept=".txt"
                >
                  <template #prepend><q-icon name="upload_file" color="primary" /></template>
                </q-file>
              </div>
              <div class="col-4">
                <q-btn
                  outline
                  color="secondary"
                  icon="cloud_upload"
                  label="Tải Lên"
                  class="full-width"
                  :disable="!uploadFile"
                  @click="uploadPrompt"
                  :loading="uploadingPrompt"
                />
              </div>
            </div>

            <!-- Prompt Preview Box -->
            <div>
              <div class="row items-center justify-between q-mb-xs">
                <span class="text-weight-bold text-caption text-grey-8">
                  Nội dung Prompt Profile: <b class="text-primary">{{ cosmos.selected }}</b>
                </span>
                <span class="text-caption text-grey-6">{{ promptText.length }} ký tự</span>
              </div>
              <q-input
                v-model="promptText"
                type="textarea"
                rows="14"
                outlined
                readonly
                class="bg-grey-1"
                placeholder="Nội dung prompt chỉ thị hệ thống sẽ hiển thị tại đây..."
              />
            </div>
          </q-card-section>
        </q-card>
      </div>
    </div>
  </q-page>
</template>

<script>
import { defineComponent, ref, reactive, onMounted } from 'vue'
import { useQuasar } from 'quasar'

export default defineComponent({
  name: 'AiConfig',

  setup () {
    const $q = useQuasar()

    // 1. VLM Engine Config
    const vlm = reactive({
      server_url: 'https://llm.ttpmsandbox.us.kg/v1',
      model_name: 'GLM-5.3-Flash',
      api_key: '',
      has_api_key: false,
      dense_frames_count: 8,
      max_vlm_frames: 8
    })
    const vlmModelOptions = ref([
      'GLM-5.3-Flash',
      'Qwen3.8-27B',
      'Qwen2.5-VL-72B-Instruct',
      'Qwen2.5-VL-7B-Instruct',
      'Qwen2.5-72B-Instruct'
    ])
    const showVlmKey = ref(false)
    const savingVlm = ref(false)
    const testingVlm = ref(false)
    const vlmTestResult = ref(null)

    // 2. Audio Engine Config
    const audio = reactive({
      server_url: 'https://llm.ttpmsandbox.us.kg/v1/audio',
      model_name: 'Internal Audio AI (Server AI)',
      api_key: '',
      has_api_key: false,
      use_deepfilter: true
    })
    const showAudioKey = ref(false)
    const savingAudio = ref(false)

    // 3. Cosmos Prompt Profiles
    const cosmos = reactive({
      selected: 'student_affairs',
      profiles: []
    })
    const promptText = ref('')
    const uploadFile = ref(null)
    const savingCosmos = ref(false)
    const uploadingPrompt = ref(false)

    const fetchAiConfig = async () => {
      try {
        const res = await fetch('/api/admin/ai-config')
        if (res.ok) {
          const data = await res.json()
          if (data.vlm) {
            vlm.server_url = data.vlm.server_url || 'https://llm.ttpmsandbox.us.kg/v1'
            vlm.model_name = data.vlm.model_name || 'GLM-5.3-Flash'
            vlm.has_api_key = !!data.vlm.has_api_key
            vlm.dense_frames_count = data.vlm.dense_frames_count || 8
            vlm.max_vlm_frames = data.vlm.max_vlm_frames || 8
            if (data.vlm.available_models && data.vlm.available_models.length) {
              vlmModelOptions.value = data.vlm.available_models
            }
          }
          if (data.audio) {
            audio.server_url = data.audio.server_url || 'https://llm.ttpmsandbox.us.kg/v1/audio'
            audio.model_name = data.audio.model_name || 'Internal Audio AI (Server AI)'
            audio.has_api_key = !!data.audio.has_api_key
            audio.use_deepfilter = data.audio.use_deepfilter !== false
          }
        }
      } catch (e) {
        console.error('Lỗi nạp cấu hình AI:', e)
      }
    }

    const saveVlmConfig = async () => {
      savingVlm.value = true
      try {
        const payload = {
          vlm_server_url: vlm.server_url,
          vlm_model_name: vlm.model_name,
          dense_frames_count: vlm.dense_frames_count
        }
        if (vlm.api_key && vlm.api_key.trim()) {
          payload.vlm_api_key = vlm.api_key.trim()
        }
        const res = await fetch('/api/admin/ai-config', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        })
        const data = await res.json()
        if (!res.ok) throw new Error(data.detail || 'Lưu cấu hình VLM thất bại')
        $q.notify({ type: 'positive', message: data.message || 'Đã lưu cấu hình VLM thành công!' })
        vlm.api_key = ''
        await fetchAiConfig()
      } catch (e) {
        $q.notify({ type: 'negative', message: e.message })
      } finally {
        savingVlm.value = false
      }
    }

    const testVlmConnection = async () => {
      testingVlm.value = true
      vlmTestResult.value = null
      try {
        const res = await fetch('/api/admin/ai-config/test-vlm', { method: 'POST' })
        const data = await res.json()
        vlmTestResult.value = data
        if (data.connected) {
          $q.notify({ type: 'positive', message: `Kết nối VLM tốt (${data.latency_ms} ms)` })
        } else {
          $q.notify({ type: 'warning', message: data.error || 'VLM Server không phản hồi' })
        }
      } catch (e) {
        vlmTestResult.value = { connected: false, error: e.message }
        $q.notify({ type: 'negative', message: 'Lỗi kiểm tra kết nối VLM: ' + e.message })
      } finally {
        testingVlm.value = false
      }
    }

    const saveAudioConfig = async () => {
      savingAudio.value = true
      try {
        const payload = {
          audio_server_url: audio.server_url,
          audio_model_name: audio.model_name,
          use_deepfilter: audio.use_deepfilter
        }
        if (audio.api_key && audio.api_key.trim()) {
          payload.audio_api_key = audio.api_key.trim()
        }
        const res = await fetch('/api/admin/ai-config', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        })
        const data = await res.json()
        if (!res.ok) throw new Error(data.detail || 'Lưu cấu hình Audio thất bại')
        $q.notify({ type: 'positive', message: data.message || 'Đã lưu cấu hình Audio thành công!' })
        audio.api_key = ''
        await fetchAiConfig()
      } catch (e) {
        $q.notify({ type: 'negative', message: e.message })
      } finally {
        savingAudio.value = false
      }
    }

    const fetchCosmosConfig = async () => {
      try {
        const res = await fetch('/api/admin/cosmos/prompt-profile')
        if (res.ok) {
          const data = await res.json()
          cosmos.selected = data.selected || 'student_affairs'
          cosmos.profiles = data.profiles || []
          await fetchPromptText(cosmos.selected)
        }
      } catch (e) {
        console.error('Lỗi tải cosmos prompt config:', e)
      }
    }

    const fetchPromptText = async (profile) => {
      try {
        const res = await fetch(`/api/admin/cosmos/prompt-profiles/${encodeURIComponent(profile)}`)
        if (res.ok) {
          const data = await res.json()
          promptText.value = data.text || ''
        }
      } catch (e) {
        promptText.value = ''
      }
    }

    const onProfileChange = (val) => {
      fetchPromptText(val)
    }

    const saveCosmos = async () => {
      savingCosmos.value = true
      try {
        const res = await fetch('/api/admin/cosmos/prompt-profile', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ profile: cosmos.selected })
        })
        const data = await res.json()
        if (!res.ok) throw new Error(data.detail || 'Lỗi lưu profile')
        $q.notify({ type: 'positive', message: `Đã áp dụng profile prompt '${cosmos.selected}'!` })
      } catch (e) {
        $q.notify({ type: 'negative', message: e.message })
      } finally {
        savingCosmos.value = false
      }
    }

    const uploadPrompt = async () => {
      if (!uploadFile.value) return
      uploadingPrompt.value = true
      try {
        const formData = new FormData()
        formData.append('prompt_file', uploadFile.value)
        const res = await fetch('/api/admin/cosmos/prompt-profiles/upload', {
          method: 'POST',
          body: formData
        })
        const data = await res.json()
        if (!res.ok) throw new Error(data.detail || 'Lỗi tải lên prompt')
        $q.notify({ type: 'positive', message: data.message || 'Tải file prompt thành công!' })
        uploadFile.value = null
        await fetchCosmosConfig()
      } catch (e) {
        $q.notify({ type: 'negative', message: e.message })
      } finally {
        uploadingPrompt.value = false
      }
    }

    const loadAll = async () => {
      await Promise.all([fetchAiConfig(), fetchCosmosConfig()])
    }

    onMounted(() => {
      loadAll()
    })

    return {
      vlm,
      vlmModelOptions,
      showVlmKey,
      savingVlm,
      testingVlm,
      vlmTestResult,
      saveVlmConfig,
      testVlmConnection,

      audio,
      showAudioKey,
      savingAudio,
      saveAudioConfig,

      cosmos,
      promptText,
      uploadFile,
      savingCosmos,
      uploadingPrompt,
      onProfileChange,
      saveCosmos,
      uploadPrompt,

      loadAll
    }
  }
})
</script>
